"""M8 artifacts explicitly distinguish unavailable real data from synthetic checks."""
from pathlib import Path
from collections import Counter
import json
import os
import uuid
import pandas as pd
from .odds_store import rows,key,utc_now
from .integrity import atomic_json,digest
from .ensemble import timestamp
from .market_comparison import compare_at,audit_matches
from .market_benchmark import benchmark,write_benchmark
from .paper_betting import ledger_view,performance,closing_line
from .reporting import table


def code_fingerprint():return key({p.name:digest(p) for p in Path(__file__).parent.glob('*.py')})


def build(db,schedules,forecasts,config,directory,decision=None,mode='prospective',infer=None,forecast_issues=None):
    decision=timestamp(decision or utc_now())
    if decision>timestamp(utc_now()):raise ValueError('Market comparison cutoff cannot be future-dated')
    opportunities,exclusions=compare_at(db,schedules,forecasts,decision,config,mode)
    frame,_,benchmark_exclusions=benchmark(db,schedules,forecasts,config,mode,infer)
    quotes=rows(db,'quotes');matches=audit_matches(db,schedules,config);wagers=ledger_view(db)
    source={'quotes':quotes,'forecasts':forecasts,'wagers':wagers,'receipts':rows(db,'receipts'),'config':config,'decision':decision.isoformat(),'mode':mode,'code':code_fingerprint(),'outcomes':[{k:(None if pd.isna(v) else str(v)) for k,v in r.items()} for r in schedules[['game_id','kickoff','home_score','away_score','completed']].to_dict('records')]}
    identifier=key(source);final=Path(directory)/identifier[:16]
    if final.exists():
        checks=json.loads((final/'outputs.json').read_text())
        if any(digest(final/name)!=sha for name,sha in checks.items()):raise ValueError('M8 report integrity failure')
        atomic_json({'run':final.name},Path(directory)/'latest.json');return final
    stage=Path(directory)/('.staging-'+uuid.uuid4().hex);stage.mkdir(parents=True)
    write_benchmark(frame,stage,config)
    pd.DataFrame(opportunities,columns=list(opportunities[0]) if opportunities else ['game_id','model','bookmaker','side','model_probability','market_no_vig_probability','ev_per_unit','paper_eligible']).to_parquet(stage/'current_opportunities.parquet',index=False)
    atomic_json(exclusions,stage/'comparison_exclusions.json');atomic_json(benchmark_exclusions,stage/'benchmark_exclusions.json')
    atomic_json(matches,stage/'match_audit.json');atomic_json(wagers,stage/'paper_ledger.json')
    matched={a['quote_id']:a['game_id'] for a in matches if a['status']=='matched'}
    atomic_json([closing_line(w,quotes,matched,config) for w in wagers],stage/'closing_lines.json')
    groups=[]
    for dimension in ['classification','model','bookmaker','threshold','season','cohort','strategy_version']:
        for value in sorted({str(w[dimension]) for w in wagers}):groups.append({'dimension':dimension,'value':value,**performance([w for w in wagers if str(w[dimension])==value])})
    pd.DataFrame(groups,columns=list(groups[0]) if groups else ['dimension','value','wagers','unique_games','realized_roi','net_simulated_profit_units']).to_csv(stage/'paper_performance.csv',index=False)
    receipts=rows(db,'receipts');fetches=[r for r in receipts if r['provider']=='the_odds_api_v4'];latest=fetches[-1] if fetches else None
    metadata={'run':identifier,'created_at':timestamp(utc_now()).isoformat(),'decision_cutoff':decision.isoformat(),'mode':mode,'protocol':config,'code_fingerprint':code_fingerprint(),'actual_quote_pairs':sum(q['source_kind'] in ['live','verified_archive'] for q in quotes),'synthetic_quote_pairs':sum(q['source_kind']=='synthetic' for q in quotes),'available_saved_forecasts':len(forecasts),'forecast_issues':forecast_issues or [],'match_status_counts':dict(Counter(a['status'] for a in matches)),'comparison_rows':len(opportunities),'real_matched_probability_games':int(frame.game_id.nunique()) if len(frame) else 0,'real_matched_rows':len(frame),'benchmark_status':'measured_matched_data' if len(frame) else 'unavailable_no_genuine_matched_graded_market_data','paper_summary':performance([w for w in wagers if w['classification']=='genuine_prospective_paper_simulation']),'reconstructed_summary':performance([w for w in wagers if w['classification']=='historical_reconstructed_paper_simulation']),'provider':{'credential_configured':bool(os.environ.get('ODDS_API_KEY')),'requests_attempted':len(fetches),'last_fetch':latest,'last_success_at':next((r['created_at'] for r in reversed(fetches) if r['status']=='success'),None),'quota':latest.get('quota') if latest else None,'implementation_documentation_review':'The implementation environment blocked the direct official guide with HTTP 403; current official GitHub provider examples were reviewed. See docs/m8/PROVIDER_REVIEW.json. Current fetch/quota observations, if any, are listed separately.'},'storage':{'raw_responses':db.execute('SELECT count(*) FROM raw').fetchone()[0],'raw_bytes':db.execute('SELECT coalesce(sum(length(content)),0) FROM raw').fetchone()[0],'database_bytes':Path(db.execute('PRAGMA database_list').fetchone()[2]).stat().st_size},'limitations':['No executable quote or actual profitability claim.','EV is conditional on binary/no-tie probability estimates.','Unknown tie/scope rules block paper issuance.','Paired week intervals are exploratory; repeat teams/cohorts/strategies are correlated.','Native combined M6/M7/M8 Windows execution is outstanding unless independently supplied.']}
    atomic_json(metadata,stage/'metadata.json')
    (stage/'MARKET_REPORT.md').write_text('# M8 research market report\n\n'+metadata['benchmark_status']+'\n\n'+table(pd.read_csv(stage/'benchmark.csv'))+'\n\nPaper simulation only. Undefined ROI is not zero profitability. Synthetic results are excluded from real market scores.\n',encoding='utf-8')
    atomic_json({p.name:digest(p) for p in stage.iterdir()},stage/'outputs.json');stage.rename(final);atomic_json({'run':final.name},Path(directory)/'latest.json');return final


def engineering_report(run,root):
    root=Path(root);run=Path(run);meta=json.loads((run/'metadata.json').read_text());qa_path=root/'docs/m8/VERIFICATION.json';qa=json.loads(qa_path.read_text()) if qa_path.exists() else {'status':'Verification pending'}
    provider=root/'docs/m8/PROVIDER_REVIEW.json';review=json.loads(provider.read_text()) if provider.exists() else {'status':'Provider review pending'}
    lines=['# M8 engineering report','', '## Implementation and preservation','', 'M8 adds an independent NFL moneyline research lab: read-only provider adapter, immutable normalized same-book pairs, CSV/JSON import, exact event matching, timestamped forecast references, no-vig/EV mathematics, fixed one-unit paper strategies, append-only settlements/corrections, market benchmarking, CLV and a Betting Lab page. No sportsbook accounts, payments, real-money execution, ML training, ensemble optimization or M9 functionality was added.','', 'M7 baseline fingerprints and source hashes are in docs/m8/BASELINE.json. The M2 champion, official SQLite, M3 ratings, M4–M7 artifacts and all 151 previously issued M7 forecasts are preserved. Existing commands remain covered by regression tests. M8 reads official SQLite with mode=ro and creates only data/m8/lab.db.','', '## Provider verification and data availability','', '```json',json.dumps(review,indent=2),'```','', 'The adapter uses apiKey, regions=us, markets=h2h, oddsFormat=american, dateFormat=iso. It does not request unrelated sports or paid historical endpoints. Official current GitHub examples confirmed event/bookmaker/market nesting, publication timestamps, historical timestamp/data envelopes and x-requests-used/remaining; x-requests-last is captured only if returned. The published current-example cost formula is markets×regions for this endpoint (one×one); no actual quota balance or charge is claimed without live observations.','', 'An environment network draft was saved for the-odds-api.com and api.the-odds-api.com; draft saving is not network activation. Review/save and Publish in environment settings is required to apply it. No credential value was requested, printed, stored or committed. Local Windows users can set ODDS_API_KEY themselves. Missing API credentials or paid archive access does not block imports, tests, existing prediction pages or offline reports.','', '## Normalization, matching and time semantics','', 'A normalized quote contains both selections from one event/book/market object and coherent timestamps. Quote publication/version time, provider snapshot time and actual capture/import time are distinct. Live responses use market or bookmaker update time as snapshot version; historical envelopes retain the provider archive time. Repeated unchanged quotes retain their first raw reference/capture; receipt events record later retrievals. Raw source bytes and hashes remain immutable. CSV needs two coherent selection rows with identities, aware times, season, source reference and prices. Undated or unverified history cannot enter verified research.','', 'Exact canonical team mapping includes current names and relocated/renamed aliases. Automatic matching requires designated home/away, NFL season and kickoff within five minutes; neutral games retain their designated teams. Reversed sides, rescheduled kickoffs, ambiguous or duplicate provider events require review. Audits are versioned by schedule fingerprints. Later duplicate events cannot change an earlier as-of decision.','', 'Prospective comparisons require the forecast creation/cutoff and quote publication/snapshot/capture to be known by the decision, all before kickoff. Historical archive imports are labeled reconstructed; their import time is never backdated. Cohorts are 24h/6h/1h with one-sided prior windows of 15/10/5 minutes. Later snapshots are excluded, including near-closing prices. Existing M7 kickoff features are too late for earlier cohorts; optional reconstruction uses new as-of features with frozen annual M7 artifacts, never retraining.','', 'M8 distinguishes actual M2 champion saved forecasts (original/revised source designation retained), M5-architecture boosting from M7 annual refits, and the fixed M7 ensemble. Historical logistic inference is labeled M2-architecture OOS refit, not a genuinely issued champion forecast. Missing artifacts/probabilities are exclusions, never substituted 0.5.','', '## Probability, EV, rules and uncertainty','', 'American +A maps to 1+A/100, −A to 1+100/abs(A); decimal arithmetic validates finite canonical quotes. Raw break-even probability is 1/D. Same-book overround is raw_home+raw_away and margin=overround−1. Proportional no-vig divides each raw probability by that sum; it is a convention, not truth. EV=pD−1 per unit, separate from percentage-point model/no-vig disagreement. +150 gives D=2.5; p=.45 gives EV=.125 per unit. These are arithmetic examples, not verified market opportunities.','', 'NFL binary models omit ties. EV is a conditional no-tie scenario; it is not an unconditional return forecast. Paper issuance requires documented game-including-overtime scope and tie push/void rules. Unknown or tie-loss/three-way rules block issuance. Missing cancel/reschedule rules cause manual review rather than invented outcomes. Quoted prices are not claimed executable. Probability shifts ±2/±5 percentage points are sensitivity scenarios, not calibrated confidence intervals.','', '## Measured real-data status','', '```json',json.dumps({k:meta[k] for k in ['actual_quote_pairs','synthetic_quote_pairs','available_saved_forecasts','match_status_counts','comparison_rows','real_matched_probability_games','real_matched_rows','benchmark_status','provider','paper_summary','reconstructed_summary','storage']},indent=2),'```','', 'Actual genuine market performance is unavailable when matched prices/outcomes are absent. No real odds history, bet return or profitability is fabricated. All-game M7 accuracy is not used as matched market evidence. CSV import and offline synthetic verification work without paid historical access.','', '## Strategies, ledger, settlement and CLV','', 'Default paper policy is champion logistic, EV strictly >3%, one simulated unit, fixed book priority then lexical identity, higher-EV side and home on ties. >0%/>3%/>5% and other model families are distinct sensitivity strategy versions, not outcome-optimized winners. Opportunity identity is game+strategy+timing cohort. Quotes, stake and probability never change after saving. Dry run writes no wagers. Corrections and changed official results append events with supersession references; manual void requires a reason.','', 'Wins return stake*(D−1) profit, losses −stake, documented pushes/voids zero. Pending/review remain ungraded. ROI divides settled profit by settled stake including refunds; it is undefined without settlements. Drawdown aggregates equal availability timestamps before equity changes; streak ties sort by game ID. Strategy/book/model/cohort/season reports retain unique-game counts and correlated exposure is not treated as independent observations.','', 'Verified CLV needs an explicitly evidenced final pregame snapshot within ten minutes, same provider/book/event/side/scope/tie rules. Merely last-observed prices are not certified closing. EntryD/closingD−1 and no-vig movement are descriptive; unavailable closing lines remain unavailable. Later closing prices never enter entry decisions.','', '## Benchmarking and diagnostics','',table(pd.read_csv(run/'benchmark.csv')),'', 'Matched scoring uses identical games for all three model families and same-book no-vig, one selected book per game/cohort. Brier, log loss, accuracy, calibration buckets/slopes and paired season-week bootstrap intervals are exported when genuine graded data exist. Separate cohorts are not pooled as independent games. Repeated teams, small samples, exploratory 2024–2025 reuse and threshold sensitivity limit inference. No operational policy is selected from evaluated P&L.','', '## Synthetic verification and operation','', 'tests/fixtures/m8/provider_v4.json contains explicitly artificial prices/events and a synthetic bookmaker. demo-m8 runs the real parsing/comparison/strategy/settlement code in an isolated temporary database, with synthetic classifications throughout. Its outputs verify software only and are excluded from actual market scores.','', '```powershell','python -m nfl_predictor.cli import-odds --odds-file reviewed_quotes.csv','python -m nfl_predictor.cli fetch-odds','python -m nfl_predictor.cli audit-odds','python -m nfl_predictor.cli compare-market','python -m nfl_predictor.cli issue-paper-bets --dry-run','python -m nfl_predictor.cli issue-paper-bets','python -m nfl_predictor.cli settle-paper-bets','python -m nfl_predictor.cli report-m8','python -m nfl_predictor.cli demo-m8','python -m pytest -q','python -m streamlit run app.py','```','', 'fetch-odds is optional and explicit; configure a local ODDS_API_KEY first. Imported rules require source references; provider responses alone do not establish house rules. Dashboard rendering only reads local data; no fetch, model fit or wager issuance occurs when opening a page. No continuous polling is implemented.','', '## Verification, runtime and Windows exception','', '```json',json.dumps(qa,indent=2),'```','', 'The combined PowerShell acceptance script retains M6/M7 checks and adds deterministic M8 checks. Live fetching is opt-in via -LiveOdds. Linux test/UI results do not certify native Windows. Runtime, storage and cache observations are machine-specific. Existing missing PBP/source-vintage and conservative final-eligibility assumptions remain.','', '## Handoff and M9 recommendations','', 'Retain the M2 champion and fixed M7 policy. Collect genuine timestamped prices and paper decisions with documented market rules, then grade independent outcomes. Verify native Windows and quota behavior with a configured account. Improve dashboard navigation/readability in M9 only after real coverage exists; M9 was not started.']
    path=root/'M8_ENGINEERING_REPORT.md';path.write_text('\n'.join(lines)+'\n',encoding='utf-8');return path
